def make_chunks(text, size):
    chunks = []
    for i in range(0, len(text), size):
        chunks.append(text[i:i+size])
    return chunks

result = make_chunks("abcdefgh", 3)

def attach_evidence(answer, docs):
    return {
        "answer": answer,
        "evidence_ids": [doc["id"] for doc in docs],
    }

result = attach_evidence("ok", [{"id": "d1"}, {"id": "d2"}])

def check_claim(answer, evidence):
    if answer["claim"] not in evidence["text"]:
        return "needs_review"
    return "supported"

status = check_claim({"claim": "Kalman"}, {"text": "PID controller basics"})

def search_tool(query):
    return "search:" + query

def write_file(path, content):
    return "write"

def chat(message):
    return "chat:" + message

def route_task(task):
    if task["type"] == "search":
        return search_tool(task["query"])
    if task["type"] == "write_file":
        return write_file(task["path"], task["content"])
    return chat(task["message"])

result = route_task({"type": "search", "query": "RAG"})

