def summarize_failures(rows):
    by_reason = {}
    for row in rows:
        reason = row.get("reason", "unknown")
        by_reason[reason] = by_reason.get(reason, 0) + 1
    return by_reason

result = summarize_failures([{"reason": "timeout"}, {"reason": "timeout"}, {"reason": "parse"}])

def should_skip(item, seen_urls):
    if item["url"] in seen_urls:
        return True
    if item.get("score", 0) < 0.5:
        return True
    return False

result = should_skip({"url": "u1", "score": 0.9}, {"u1"})

